90	                if (line.isEmpty() || line.startsWith("--")) {
91	                    continue;
92	                }
93	                current.append(line).append(' ');
94	                if (line.endsWith(";")) {
95	                    String stmtSql = current.toString().trim();
96	                    stmtSql = stmtSql.substring(0, stmtSql.length() - 1);
97	                    if (!stmtSql.isEmpty()) {
98	                        stmt.execute(stmtSql);
99	                    }
100	                    current.setLength(0);
101	                }
102	            }
103	            String tail = current.toString().trim();
104	            if (!tail.isEmpty()) {
105	                stmt.execute(tail);
106	            }
107	        } catch (Exception e) {
