package com.ahope.ds.common.extension.resolver;

import java.lang.annotation.Annotation;

import jakarta.servlet.http.HttpServletRequest;

import org.springframework.core.MethodParameter;
import org.springframework.web.bind.support.WebArgumentResolver;
import org.springframework.web.bind.support.WebDataBinderFactory;
import org.springframework.web.context.request.NativeWebRequest;
import org.springframework.web.method.support.HandlerMethodArgumentResolver;
import org.springframework.web.method.support.ModelAndViewContainer;

import com.ahope.ds.common.bean.ParamMap;
import com.ahope.ds.common.exception.RuntimeLogicException;
import com.ahope.ds.common.extension.annotation.RequestParamMap;
import com.ahope.ds.common.util.CommonUtil;

public class RequestParamMapArgumentResolver implements HandlerMethodArgumentResolver {
	public Object resolveArgument(MethodParameter param,
			ModelAndViewContainer mnv, NativeWebRequest request,
			WebDataBinderFactory binderFactory) throws Exception {

		Annotation[] paramAnns = param.getParameterAnnotations();  
		Class<?> paramType = param.getParameterType();  

        for (Annotation paramAnn : paramAnns) {

        	if (RequestParamMap.class.isInstance(paramAnn)) {  

        		if(paramType.isAssignableFrom(ParamMap.class)){

	            	HttpServletRequest httprequest = (HttpServletRequest) request.getNativeRequest();
	            	ParamMap paramMap = new ParamMap(httprequest);
	            	RequestParamMap reqAttr = (RequestParamMap)paramAnn;
	            	if(reqAttr.requiredValues().length > 0) {
            			for(String requiredValue : reqAttr.requiredValues()) {
            				if(CommonUtil.isNull(paramMap.get(requiredValue))){
            					CommonUtil.deviceLogWrite(httprequest);
            					throw new RuntimeLogicException("MISSING_REQUIRED_VALUE : ["+requiredValue+"]", "001");
            				}
            			}
            		}
	            	return new ParamMap(httprequest); 
	            } else {
	            	return WebArgumentResolver.UNRESOLVED;
	            }
        	}
        }  

		return WebArgumentResolver.UNRESOLVED;
	}

	public boolean supportsParameter(MethodParameter parameter) {
		return parameter.hasParameterAnnotation(RequestParamMap.class);
	}

}

