27	
28	@Component
29	public class AdminLoginInterceptor implements HandlerInterceptor {
30	
31		private static final Logger logger = LoggerFactory.getLogger(AdminLoginInterceptor.class);
32	
33		@Autowired
34		private LoginDAO dao;
35	
36		@Autowired
37		SessionLocaleResolver localeResolver;
38	
39		@Override
40		public boolean preHandle(HttpServletRequest req, HttpServletResponse res, Object handler) throws Exception {
41	
42			MDC.put("RID", CommonUtil.getRandomStr());
43	
44			String[] ajaxUriList = {"/ajax","/chargeFee/search","/usage/search","/v3/api-docs"};
45			boolean ajaxFlag = false;
46			HttpSession session = req.getSession();
47			for (String ajaxUri : ajaxUriList) {
48				if (req.getRequestURI().indexOf(ajaxUri) > 0) {
49					ajaxFlag = true;
50					break;
51				}
52			}
53	
54			if(CommonUtil.isNull(session.getAttribute("loginAccountSeq"))) {
55				//ajax에 대한 요청인데 세션이 만료된 경우
56				if(ajaxFlag) {
57					res.sendError(401);
58				} else {
59					res.sendRedirect("/web/login");
60				}
61				return false;
62			} else {
63				//로그인 중복 체크
64				ParamMap param = new ParamMap();
65				param.put("accountSeq", session.getAttribute("loginAccountSeq"));
66				param.put("loginToken", session.getAttribute("loginToken"));
67				if(!dao.checkLoginToken(param)) {
68					session.invalidate();
69					if(ajaxFlag) {
70						res.sendError(401);
71					} else {
72						res.sendRedirect("/web/login?duplicateLogin=Y");
73					}
74					return false;
75				}
76			}
77	
78			long accountSeq = ((Number) session.getAttribute("loginAccountSeq")).longValue();
79			ResultMap accountInfo = dao.getAccountInfo(accountSeq);
80			String authz = accountInfo.getString("authz");
81			String loginId = (String) session.getAttribute("loginId");
82	
83			String adminHome = "/web/admin";
84			if ((!Authz.SYSTEM.equals(authz) && !Authz.SUPER.equals(authz) && req.getRequestURI().matches(adminHome + "/ecgis(/(excel/)?new)?"))
85			        || (!Authz.SYSTEM.equals(authz) && !Authz.SUPER.equals(authz) && req.getRequestURI().matches(adminHome + "/agpss(/(excel/)?new)?"))
86					|| (!Authz.SYSTEM.equals(authz) && !Authz.SUPER.equals(authz) && req.getRequestURI().matches(adminHome + "/beacons/(excel/)?new"))
87					|| (!Authz.SYSTEM.equals(authz) && !Authz.SUPER.equals(authz) && req.getRequestURI().matches(adminHome + "/quality.*"))
88					|| (Authz.DEVICE.equals(authz) && !req.getRequestURI().matches(adminHome + "/devices.*"))
89					|| (Authz.CONSULTING.equals(authz) && !req.getRequestURI().matches(adminHome + "/qos.*"))) {
90				res.sendError(403);
91				return false;
92			}
93			
94			// 시스템 관리자 외 블랙리스트
95			if (!Authz.SYSTEM.equals(authz) &&(
96			        req.getRequestURI().equals(adminHome + "/members/excel/make") ||
97			        req.getRequestURI().equals(adminHome + "/usage/member/excel/make") ||
98			        req.getRequestURI().equals(adminHome + "/quota/members/excel/make") ||
99			        req.getRequestURI().equals(adminHome + "/traffic/excel/make")
100			        )
101			    ) {
102			    res.sendError(403);
103	            return false;
104			}
105	
106			logger.info("[LoginInterceptor] preHandle, URI: " + req.getRequestURI());
107			logger.info("[LoginInterceptor] preHandle, Method: " + req.getMethod());
108	
109			String method = req.getMethod();
110			if(!"GET".equals(method)) {
111				logger.info("[LoginInterceptor] preHandle, Account: #{} {} [{}]", accountSeq, loginId, authz);
112			}
113	
114	
115			if (req.getRequestURI().matches(adminHome + "/members.*")) {
116				// 선택 가입자 인터넷 차단 등록 / 해제
117				if("PUT".equals("method")
118					&& !Authz.SYSTEM.equals(authz)
119					&& !Authz.SUPER.equals(authz)
120					&& req.getRequestURI().matches(".*/internet-block")) {
121					res.sendError(403);
122					return false;
123				}
124	
125				// PUT: 가입자 수정, 복구, 복구 취소, 기기변경 DELETE: 가입자 삭제
126				if ("PUT".equals(method) || "DELETE".equals(method)) {
127					if (!Authz.SYSTEM.equals(authz) && !Authz.SUPER.equals(authz) && !Authz.JOIN.equals(authz)) {
128						res.sendError(403);
129						return false;
130					}
131				}
132	
133				// 가입자 등록, 가입자 엑셀 등록
134				if ("POST".equals(method)
135					&& (req.getRequestURI().equals(adminHome + "/members/")
136					|| req.getRequestURI().equals(adminHome + "/members/excel"))) {
137					if (!Authz.SYSTEM.equals(authz) && !Authz.SUPER.equals(authz) && !Authz.JOIN.equals(authz)) {
138						res.sendError(403);
139						return false;
140					}
141				}
142	
143				// 그룹 관리자의 비허용 고객사 접근 방지
144				if (Authz.GROUP.equals(authz)) {
145					boolean hasClient = false;
146					String loginClientSeq = session.getAttribute("loginClientSeq").toString();
147					for (String clientSeq : accountInfo.getString("clients").split(",")) {
148						if (clientSeq.equals(loginClientSeq))
149							hasClient = true;
150					}
151					if (!hasClient) {
152						res.sendError(403);
153						return false;
154					}
155				}
156			}
157	
158			// 데이터 관리 메뉴 접근 방지 - 데이터 관리(부가 서비스) 설정이 01이 아니면
159			if(req.getRequestURI().matches(adminHome + "/quota.*")
160					&& !"01".equals(session.getAttribute("loginQuotaOnOff"))) {
161				res.sendError(403);
162				return false;
163			}
164	
165			if (!CommonUtil.isNull(session.getAttribute("expiredPw"))) {
166				boolean isExpiredPw = (boolean) session.getAttribute("expiredPw");
167				if (isExpiredPw) {
168					res.sendRedirect("/web/mypage/password");
169					return false;
170				}
171			}
172	
173			// DataSource 유효성 체크
174			String sqlSessionTemplate = (String)session.getAttribute(Constants.SQL_SESSION_TEMPLATE_NAME);
175			if (!CommonUtil.isNull(sqlSessionTemplate)) {
176				try {
177					DSApplicationContext.getBean(sqlSessionTemplate, SqlSessionTemplate.class);
178				} catch (NoSuchBeanDefinitionException ne) {
179					throw new ResourceNotFoundException("NOT_FOUNT_SQL_SESSION_BEAN", "888");
180				}
181			}
182	
183			dao.updateLoginDate(((Number) session.getAttribute("loginAccountSeq")).longValue());
184	
185			if (CommonUtil.isNull(session.getAttribute("loginClientSeq"))) {
186				session.setAttribute("loginClientSeq", -1);
