import com.ahope.ds.common.aws.kms.AwsKmsEncryptionService;
import com.ahope.ds.common.bean.LogInfo;
import com.ahope.ds.common.constnats.Constants;
import com.ahope.ds.common.exception.LogicException;
import com.ahope.ds.common.extension.annotation.NoAuth;
import com.ahope.ds.common.util.CommonUtil;
import com.fasterxml.jackson.databind.ObjectMapper;

@Component
public class ClientLoginInterceptor implements HandlerInterceptor {

	protected Logger logger = LoggerFactory.getLogger(ClientLoginInterceptor.class);
	protected Logger lgLogger = LoggerFactory.getLogger("lgLogger");

	private static final DateTimeFormatter TOKEN_DATE_FORMAT = DateTimeFormatter.ofPattern("yyyyMMddHHmmss");

	@Autowired
	@Qualifier("tokenEncryptionService")
	private AwsKmsEncryptionService tokenEncryptionService;

	@Autowired
	private SessionLocaleResolver localeResolver;

	@SuppressWarnings("unchecked")
	@Override
	public boolean preHandle(HttpServletRequest req, HttpServletResponse res, Object handler) throws Exception {

		MDC.put("RID", CommonUtil.getRandomStr());

		HttpSession session = req.getSession();

		session.setAttribute("osInfo", CommonUtil.nvl(req.getHeader("X-OS-Version")));
		session.setAttribute("networkInfo", CommonUtil.nvl(req.getHeader("networkInfo")));
		session.setAttribute("deviceModel", CommonUtil.nvl(req.getHeader("X-Model")));
		session.setAttribute("deviceInfo", CommonUtil.nvl(req.getHeader("X-Manufacturer")));

		logger.info("[ LOCALE ] " + req.getHeader("lang"));
		String localeStr = Constants.LOCALE_KOREAN;
		if (!CommonUtil.isNull(req.getHeader("lang"))) {
			localeStr = req.getHeader("lang");
			if (!localeStr.equals(Constants.LOCALE_ENGLISH)
					&& !localeStr.equals(Constants.LOCALE_CHINESE)
					&& !localeStr.equals(Constants.LOCALE_VIETNAMESE)) {
				localeStr = Constants.LOCALE_KOREAN;
			}
		}
		Locale locale = new Locale(localeStr);
		localeResolver.setLocale(req, res, locale);
		session.setAttribute("lang", locale);

		if (handler instanceof HandlerMethod) {
			HandlerMethod handlerMethod = (HandlerMethod) handler;
			if (handlerMethod.hasMethodAnnotation(NoAuth.class)) {
				return true;
			}
		}

		// 통합 로그용 LogInfo 생성
		LogInfo logInfo = new LogInfo(
				"SVC"
				, CommonUtil.nvl(req.getRemoteAddr())
				, (String) session.getAttribute("deviceInfo")
				, CommonUtil.nvl(req.getHeader("X-OS-Version"))
				, (String) session.getAttribute("networkInfo")
				, ""
				, CommonUtil.nvl(req.getHeader("X-Model"))
				, "1"
				, ""
				, ""
				, ""
				, ""
				, ""
				, ""
				, "");

		String authorization = req.getHeader("Authorization");

		if (CommonUtil.isNull(authorization)) {
			logInfo = getServiceCode(req.getRequestURI(), logInfo);
			logInfo.setRESULT_CODE(Constants.MISSING_TOKEN_VALUE_CODE);
			lgLogger.info(logInfo.toString());
			throw new LogicException(Constants.MISSING_TOKEN_VALUE_MSG, Constants.MISSING_TOKEN_VALUE_CODE);
		}

		if (!authorization.startsWith("Bearer ")) {
			logInfo = getServiceCode(req.getRequestURI(), logInfo);
			logInfo.setRESULT_CODE(Constants.INVALID_TOKEN_CODE);
			lgLogger.info(logInfo.toString());
			throw new LogicException(Constants.INVALID_TOKEN_MSG, Constants.INVALID_TOKEN_CODE);
		}

		String accessToken = authorization.substring("Bearer ".length()).trim();
		String decrypted;

		try {
			decrypted = tokenEncryptionService.decrypt(accessToken);
			logger.info("복호화 토큰(임시): " + decrypted); // TODO DELETE HW
		} catch (Exception e) {
			logger.error("[ClientLoginInterceptor] Token decryption failed", e);
			logInfo = getServiceCode(req.getRequestURI(), logInfo);
			logInfo.setRESULT_CODE(Constants.INVALID_TOKEN_CODE);
			lgLogger.info(logInfo.toString());
			throw new LogicException(Constants.INVALID_TOKEN_MSG, Constants.INVALID_TOKEN_CODE);
		}

		ObjectMapper objectMapper = new ObjectMapper();
		Map<String, Object> tokenPayload = objectMapper.readValue(decrypted, Map.class);

		String tokenType = (String) tokenPayload.get("tokenType");
		if (!Constants.TOKEN_TYPE_ACCESS.equals(tokenType)) {
			logInfo = getServiceCode(req.getRequestURI(), logInfo);
			logInfo.setRESULT_CODE(Constants.INVALID_TOKEN_TYPE_CODE);
			lgLogger.info(logInfo.toString());
			throw new LogicException(Constants.INVALID_TOKEN_TYPE_MSG, Constants.INVALID_TOKEN_TYPE_CODE);
		}

		String expiredAt = (String) tokenPayload.get("expiredAt");
		String now = LocalDateTime.now().format(TOKEN_DATE_FORMAT);
		if (now.compareTo(expiredAt) > 0) {
			logInfo = getServiceCode(req.getRequestURI(), logInfo);
			logInfo.setRESULT_CODE(Constants.TOKEN_EXPIRED_CODE);
			lgLogger.info(logInfo.toString());
			throw new LogicException(Constants.TOKEN_EXPIRED_MSG, Constants.TOKEN_EXPIRED_CODE);
		}

		// memberSeq, clientSeq 세션 설정
		long memberSeq = ((Number) tokenPayload.get("memberSeq")).longValue();
		long clientSeq = ((Number) tokenPayload.get("clientSeq")).longValue();
		session.setAttribute("memberSeq", memberSeq);
		session.setAttribute("clientSeq", clientSeq);

		return true;
	}

	@Override
	public void postHandle(HttpServletRequest req, HttpServletResponse res, Object handler, ModelAndView mnv) throws Exception {
		logger.info("[ClientLoginInterceptor] postHandle");
	}

	@Override
	public void afterCompletion(HttpServletRequest req, HttpServletResponse res, Object handler, Exception e) throws Exception {
		logger.info("[ClientLoginInterceptor] afterCompletion");
	}

	private LogInfo getServiceCode(String requestURI, LogInfo logInfo) {
		String serviceClass = "";
		String legacyClass = "";
		if (Pattern.matches("^(\\/client\\/checklist).*", requestURI)) {
			serviceClass = "S01";
		} else if (Pattern.matches("^(\\/client\\/version).*", requestURI)) {
			serviceClass = "S02";
		} else if (Pattern.matches("^(\\/client\\/init).*", requestURI)) {
			serviceClass = "S03";
		} else if (Pattern.matches("^(\\/client\\/sync).*", requestURI)) {
			serviceClass = "S04";
		} else if (Pattern.matches("^(\\/client\\/terms).*", requestURI)) {
			serviceClass = "S05";
		} else if (Pattern.matches("^(\\/client\\/auth).*", requestURI)) {
			serviceClass = "S06";
		} else if (Pattern.matches("^(\\/client\\/notice).*", requestURI)) {
			serviceClass = "S07";
		} else if (Pattern.matches("^(\\/client\\/change).*", requestURI)) {
			serviceClass = "S08";
		} else if (Pattern.matches("^(\\/client\\/changed).*", requestURI)) {
			serviceClass = "S09";
		} else if (Pattern.matches("^(\\/client\\/location).*", requestURI)) {
			serviceClass = "S10";
		} else if (Pattern.matches("^(\\/client\\/refresh).*", requestURI)) {
			serviceClass = "S11";
		}

		logInfo.setSVC_CLASS(serviceClass);
		logInfo.setLEGACY_CLASS(legacyClass);

		return logInfo;
	}
}

