package com.ahope.ds.common.web.controller;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;

import org.mybatis.spring.MyBatisSystemException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.MissingRequestHeaderException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.ResponseBody;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.servlet.ModelAndView;

import com.ahope.ds.common.bean.ClientResultMap;
import com.ahope.ds.common.constnats.Constants;
import com.ahope.ds.common.exception.LogicException;
import com.ahope.ds.common.exception.ResourceNotFoundException;
import com.ahope.ds.common.exception.RuntimeLogicException;

public class CommonClientController {

	protected Logger logger = LoggerFactory.getLogger(this.getClass());
	protected Logger lgLogger = LoggerFactory.getLogger("lgLogger");

	protected String JSON_VIEW = "jsonView";

	@ResponseStatus(HttpStatus.OK)
	@ResponseBody
	@ExceptionHandler(Exception.class)
	public ModelAndView exceptionHandler(HttpServletRequest request, HttpServletResponse response, Exception ex) {
		logger.debug("start URI : " + request.getRequestURI());

		String code;
		String message;

		switch (ex) {
			case MissingRequestHeaderException mrhEx -> {
				code = Constants.MISSING_REQUIRED_VALUE_CODE;
				message = Constants.MISSING_REQUIRED_VALUE_MSG + ": " + mrhEx.getHeaderName();
			}
			case LogicException le -> {
				code = le.getCode();
				message = le.getMessage();
			}
			case RuntimeLogicException rle -> {
				code = rle.getCode();
				message = rle.getMessage();
			}
			case MyBatisSystemException mbEx -> {
				if (mbEx.getMessage() != null
						&& mbEx.getMessage().contains("TooManyResultsException")) {
					code = Constants.TOO_MANY_RESULTS_CODE;
					message = Constants.TOO_MANY_RESULTS_MSG;
				} else {
					code = Constants.DB_CONNECTION_FAIL_CODE;
					message = Constants.DB_CONNECTION_FAIL_MSG;
				}
			}
			default -> {
				code = Constants.UNKNOWN_ERR_CODE;
				message = Constants.UNKNOWN_ERR_MSG;
				logger.error("Unhandled exception [{}]: {}", ex.getClass().getSimpleName(), ex.getMessage(), ex);
			}
		}

		if (!(ex instanceof MyBatisSystemException) && !Constants.UNKNOWN_ERR_CODE.equals(code)) {
			logger.error("Handled exception [{}] code={}, message={}", ex.getClass().getSimpleName(), code, message);
		}

		return buildErrorResponse(code, message);
	}

	@ExceptionHandler(ResourceNotFoundException.class)
	public ModelAndView notFoundExceptionHandler(HttpServletRequest request, HttpServletResponse response,
			ResourceNotFoundException ex) {
		return buildErrorResponse(Constants.NOT_FOUND_CODE, Constants.NOT_FOUND_MSG);
	}

	private ModelAndView buildErrorResponse(String code, String message) {
		ClientResultMap result = new ClientResultMap();
		result.setCode(code);
		result.setMessage(message);

		ModelAndView mav = new ModelAndView(JSON_VIEW);
		mav.addAllObjects(result);
		return mav;
	}
}

