	public ResultMap getPersonalDecryption(ParamMap param) {
		ResultMap result = new ResultMap();
		String cryptoContent = param.getString("cryptoContent").trim();
		try {
			result.put("cryptoResult", dataEncryptionService.decrypt(cryptoContent));
		} catch (RuntimeException e) {
			result.setErr("115");
			logger.warn("[getPersonalDecryption] invalid ciphertext: {}", e.getMessage());
		} catch (Exception e) {
			result.setErr("001");
			logger.error("[getPersonalDecryption] {}", e.getMessage());
		}
		return result;
	}
