    public ResultMap deleteGroups(ParamMap paramMap) throws LogicException {
        ResultMap result = new ResultMap();
        DataSourceTransactionManager transactionManager = getDataSourceTransactionManager(paramMap);
        TransactionStatus transactionStatus = transactionManager.getTransaction(new DefaultTransactionDefinition());

        try {
            int affected = dao.deleteGroups(paramMap);
            if (affected == 0) {
                throw new LogicException(GROUP_NOT_FOUND, CODE_GROUP_NOT_FOUND);
            }
            result.put("removeCnt", affected);

            dao.disbandMemberGroups(paramMap);
            transactionManager.commit(transactionStatus);
        } catch (LogicException e) {
            transactionManager.rollback(transactionStatus);
            throw e;
        } catch (Exception e) {
            transactionManager.rollback(transactionStatus);
            logger.error(e.getMessage());
            throw new LogicException(UNKNOWN_ERROR, CODE_UNKNOWN_ERROR);
        }

        result.setErr(CODE_SUCCESS);
        return result;
    }
